# LATER-STEP\n\"\"\"\nmetric_summary.py\nSummarize recent metric trends or anomalies.\n\"\"\"\n\nfrom observability_client import ManagedMetricsClient\nfrom observability_models import normalize_query_response\n\ndef metric_summary(metric_name: str, start_time: str, end_time: str) -> str:\n    \"\"\"Return a concise textual summary of the metric over the window.\n    \n    Includes basic statistics and any obvious anomalies.\n    \"\"\"\n    client = ManagedMetricsClient()\n    raw = client.query_metric_window(metric_name, start_time, end_time)\n    points = normalize_query_response(raw)\n    if not points:\n        return \"No data for the requested window.\"\n    values = [p.value for p in points]\n    avg = sum(values) / len(values)\n    trend = \"steady\" if max(values) - min(values) < 0.1 * avg else \"spiky\"\n    return (f"Metric {metric_name} over {start_time} – {end_time}: avg={avg:.2f}, min={min(values):.2f}, "\n            f"max={max(values):.2f}, trend={trend}")
